import{_ as t,o as n,c as o,a2 as r}from"./chunks/framework.sc8Z_ZE3.js";const p=JSON.parse('{"title":"Known limitations","description":"","frontmatter":{},"headers":[],"relativePath":"start/known-limitations.md","filePath":"start/known-limitations.md"}'),s={name:"start/known-limitations.md"};function a(i,e,l,d,h,u){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h1><p>Octryx AI 0.0.2-alpha ships with these known limitations. Feature pages list their own smaller limits too; see for example the <a href="/docs/review-bot/limits">review bot&#39;s limits</a> and <a href="/docs/start/status">Status and results</a>.</p><p><strong>Security note:</strong> 0.0.2 fixes <a href="https://github.com/octryx-ai/octryx/security/advisories/GHSA-h4xh-8wqf-rxj4" target="_blank" rel="noreferrer">GHSA-h4xh-8wqf-rxj4</a>: in v0.0.1-alpha the Codex device mode applied a repository&#39;s own Codex configuration. Upgrade from v0.0.1-alpha; see <a href="/docs/install/upgrade#from-0-0-1-alpha-to-0-0-2">Upgrade</a>.</p><h2 id="server-runners" tabindex="-1">Server runners <a class="header-anchor" href="#server-runners" aria-label="Permalink to &quot;Server runners&quot;">​</a></h2><p>See <a href="/docs/install/runners">Server runners</a>.</p><ul><li><strong>gVisor is not tested on a real gVisor host yet.</strong> The runtime can be configured (Compose and Helm) and is enforced, but Docker Desktop and kind cannot run it, and no chat turn or workflow run has run on gVisor itself.</li><li><strong>A restarted runner enrolls as a new device.</strong> The old one stays offline in <strong>Admin › Devices</strong> until you remove it. A Codex conversation in progress on that runner is lost with its container.</li><li><strong>The runner image is about 5 GB</strong>: it carries two browser builds for the browser tools.</li><li><strong>A runner serves one person in one Workspace at a time.</strong> More parallel work needs more runners.</li><li><strong>Runners run Codex with governed models only.</strong> A phase that needs a person&#39;s seat waits for a <a href="/docs/work/seat-takeover">seat takeover</a>.</li><li><strong>Files the turn&#39;s hooks write in the session folder stay writable by the agent</strong>, on a runner as on a device.</li></ul><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><ul><li><strong>End-of-turn checks of a Codex device turn run repository tools outside Codex&#39;s sandbox</strong>: style tools, build wrappers, tools from <code>node_modules/.bin</code> or <code>.venv/bin</code>. A malicious repository could tamper with those checks: use device turns only on repositories you trust.</li></ul><h2 id="server-runner-pool-and-seats" tabindex="-1">Server runner pool and seats <a class="header-anchor" href="#server-runner-pool-and-seats" aria-label="Permalink to &quot;Server runner pool and seats&quot;">​</a></h2><ul><li><strong>A server-runner target that needs your own seat</strong> cannot be chosen in the web app yet; it comes only from the API, a handoff, triage or a saved target.</li><li><strong>A &quot;needs your device&quot; pause keeps its text</strong> after a device comes online; continuing the run refreshes it.</li><li><strong>No pool page on the phone yet.</strong> Pool entries appear on the phone only in the attention list (<strong>Needs you</strong>). There, a seat entry is refused to someone without a device that can run it right now, instead of being taken and waiting.</li></ul><h2 id="workflows-tasks-and-runs" tabindex="-1">Workflows, tasks and runs <a class="header-anchor" href="#workflows-tasks-and-runs" aria-label="Permalink to &quot;Workflows, tasks and runs&quot;">​</a></h2><ul><li><strong>A finished server-runner run&#39;s composer still says &quot;Run on: your device&quot;</strong> (with the runner&#39;s folder), although the run bar says it ran on the server runners.</li><li><strong>The collapsed run bar shows a generic line for a paused run</strong>; open the run for the reason.</li><li><strong>Team work items in a run that needs a seat</strong> are not covered by tests yet.</li><li><strong>Demo:</strong> the sample run keeps its sample pull request open, so a new run on the same sample ticket fails when it tries to open a second pull request.</li></ul><h2 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h2><ul><li>Codex 0.169 still runs a tool call when it cannot start the hook, or when the hook&#39;s runner fails or passes its deadline before the guard answers.</li><li>A full-access turn on a person&#39;s own device is no boundary against the agent, as Claude Code&#39;s permission-skipping mode is not.</li></ul><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><ul><li><strong>GitHub Copilot is not supported</strong> as a model provider yet.</li><li><strong>After a model failover</strong>, a review step may name the first model tried instead of the model that answered.</li><li><strong>MCP activity records both engines as the same client</strong> (<code>mcp-client</code>).</li><li><strong>On the coding-agent gateway, model answers are not scanned for secrets.</strong> Protection happens on the request side, so a model cannot echo a secret it never received. (The platform&#39;s own model calls do check their replies; see <a href="/docs/security/sensitive-content#where-reroute-does-not-apply">Sensitive content handling</a>.)</li><li><strong>Temporary AWS credentials expire</strong>, and the Bedrock model stops working then: enter new ones in <strong>Admin › Models</strong>, or use a long-lived key pair.</li></ul><h2 id="sensitive-content-handling" tabindex="-1">Sensitive content handling <a class="header-anchor" href="#sensitive-content-handling" aria-label="Permalink to &quot;Sensitive content handling&quot;">​</a></h2><p>See <a href="/docs/security/sensitive-content">Sensitive content handling</a> for how it works.</p><ul><li><strong>Threat model.</strong> The coding-agent gateway protects against accidental leakage by your own coding agent and against prompt injection arriving in its requests. It does not defend against a deliberately evasive client: Claude Code and Codex are your own programs and can reach any provider directly.</li><li><strong>Opaque fields are skipped by key name, without validation.</strong> These are provider-signed state and inline media data; see <a href="/docs/security/sensitive-content#the-opaque-key-list">the opaque key list</a>.</li><li><strong>Prompt injection on the gateway</strong> is checked in the newest turn&#39;s content only (your message and the tool results it carries), not in tool definitions or the client&#39;s system prompt.</li><li><strong>A ChatGPT seat cannot be rerouted.</strong> A kind set to reroute or mask and reroute refuses a Codex seat request (<code>content_route_unavailable</code>).</li></ul><h2 id="work-items-and-pull-requests" tabindex="-1">Work items and pull requests <a class="header-anchor" href="#work-items-and-pull-requests" aria-label="Permalink to &quot;Work items and pull requests&quot;">​</a></h2><ul><li><strong>Pull requests are recorded internally.</strong> A workflow run records the pull request it opens, and while it waits for the merge or decline it asks for a refresh of that record. The refresh reads GitHub and Bitbucket pull requests only, and only while the repository&#39;s connection still serves the host the pull request was recorded on (otherwise <code>host_mismatch</code>). GitLab runs are watched through their own poll and webhook. There is no pull request page and no manual sync or refresh. The chat lists a session&#39;s pull requests, and each links its run, session and approved plan.</li><li><strong>A work item and an intake keep the Workspace they were created in.</strong> A change of Workspace is refused (<code>409 workspace_immutable</code>).</li><li><strong>There is no pull request traceability sync for design delivery.</strong> The release and checkpoint trace syncs remain.</li></ul><h2 id="workspaces-people-and-audit" tabindex="-1">Workspaces, people and audit <a class="header-anchor" href="#workspaces-people-and-audit" aria-label="Permalink to &quot;Workspaces, people and audit&quot;">​</a></h2><ul><li><strong>In a shared Workspace every member can read every chat in it.</strong> This is intended, for team transparency; private Workspaces stay private.</li><li><strong>Channel and Teams bots act as the Workspace owner</strong>; a shared Workspace has no per-person channel identity yet.</li><li><strong>Messages of a deleted user show under the session&#39;s owner</strong>, and prompts Octryx AI writes for teamwork and reviews carry the thread owner as their author.</li><li><strong>Audit rows of a Workspace that was later deleted</strong> become visible to admins.</li><li><strong>Knowledge retention runs are visible to platform admins only</strong>, not to a Workspace&#39;s owner.</li><li><strong>The admin data-classification view</strong> reports the built-in platform preset as coming from the environment.</li></ul><h2 id="accounts-and-phones" tabindex="-1">Accounts and phones <a class="header-anchor" href="#accounts-and-phones" aria-label="Permalink to &quot;Accounts and phones&quot;">​</a></h2><ul><li><strong>An upload signed for a user who was then deactivated</strong>, or for a phone that was then revoked, is still accepted until that token expires.</li></ul><h2 id="running-the-demo" tabindex="-1">Running the demo <a class="header-anchor" href="#running-the-demo" aria-label="Permalink to &quot;Running the demo&quot;">​</a></h2><ul><li><strong>The demo&#39;s hardware needs are not re-measured for 0.0.2.</strong> The runner image is about 4.9 GB and the platform image about 2.4 GB, plus LiteLLM. The <a href="/docs/start/first-run">First run</a> figures (at least 4 GB memory, 25 GB free disk) follow the README and are a lower bound until measured.</li></ul>',27)])])}const g=t(s,[["render",a]]);export{p as __pageData,g as default};
